class Solution {
  public int largestInteger(int[] nums, int k) {
    int best = -1;
    for (int x = 0; x <= 50; x++) {
      int windows = 0;
      for (int i = 0; i + k <= nums.length; i++) {
        for (int j = i; j < i + k; j++) {
          if (nums[j] == x) {
            windows++;
            break;
          }
        }
      }
      if (windows == 1) best = x;
    }
    return best;
  }
}
